let sessionId, state, busy=false;
const $=id=>document.getElementById(id);
const element=(tag,text,className)=>{const el=document.createElement(tag);el.textContent=text;if(className)el.className=className;return el;};
async function api(route,body){const response=await fetch(route,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const data=await response.json();if(!response.ok)throw new Error(data.error||'Could not complete the request.');return data;}
function setBusy(value){busy=value;$('ask').disabled=value||!!state?.current.end;$('restart').disabled=value;$('ask').firstChild.textContent=value?'Finding a clip… ':'Ask patient ';document.querySelectorAll('#options button, #endings button').forEach(b=>b.disabled=value);}
function showState(data){state=data;$('patient-line').textContent=data.current.patient;$('clip-label').textContent='CLIP '+data.current.id;
  const video=$('video');video.pause();video.hidden=!data.current.videoAvailable;$('video-placeholder').hidden=data.current.videoAvailable;$('video-error').hidden=true;
  if(data.current.videoAvailable){video.src='/videos/'+encodeURIComponent(data.current.id)+'.mp4';video.play().catch(()=>{});}else{video.removeAttribute('src');video.load();$('placeholder-title').textContent='Video not connected';$('placeholder-detail').textContent='The original patient transcript is available below. Connect your MP4 folder to play this clip.';}
  $('options').replaceChildren(...data.options.map(c=>{const b=element('button',c.doctor);b.type='button';b.addEventListener('click',()=>ask(c.doctor,c.id));return b;}));
  $('endings').replaceChildren(...data.endings.map(c=>{const b=element('button',c.doctor);b.type='button';b.addEventListener('click',()=>ask(c.doctor,c.id));return b;}));
  $('ending-choices').hidden=data.current.end;
  $('question').disabled=data.current.end;$('question').placeholder=data.current.end?'Consultation ended. Review the areas you covered.':'What would you like to ask Miss Smith?';$('ask').disabled=data.current.end;
}
async function start(){setBusy(true);$('message').textContent='';try{const data=await api('/api/session',{});sessionId=data.sessionId;$('history').replaceChildren(element('p',data.current.doctor,'hint'));$('turn-count').textContent='0 questions';showState(data);$('scripted').open=false;$('patient-response').open=false;const status=await api('/api/status');$('mode').textContent=status.aiReady?'Local AI connected':'Script preview';$('mode').classList.toggle('active',status.aiReady);$('mode-help').textContent=status.aiReady?'Your question is matched to an existing video by the local AI. Patient replies remain the original script.':'AI is not connected. Use the scripted questions below to preview the patient’s existing consultation.';}catch(e){$('message').textContent=e.message;}finally{setBusy(false);}}
async function ask(question,clipId){if(busy)return;setBusy(true);$('message').textContent='';try{const data=await api('/api/question',{sessionId,question,...(clipId?{clipId}:{})});if(data.matched){const turn=element('div','','turn');turn.append(element('strong','YOU'),element('p',question),element('strong','MISS SMITH'),element('p',data.current.patient),element('small','Clip '+data.current.id+' · '+(data.selection==='ai'?'AI selected an existing clip':data.selection==='context'?'Context selected an existing clip':'Scripted question')));$('history').append(turn);$('turn-count').textContent=data.choices.length+' questions';$('question').value='';showState(data);if(data.current.end)review();}else{$('message').textContent=data.message;}}catch(e){$('message').textContent=e.message;}finally{setBusy(false);}}
async function review(){if(!state)return;try{state=await api('/api/finish',{sessionId});}catch(e){$('message').textContent=e.message;return;}const content=$('feedback-content');content.replaceChildren();for(const covered of [true,false]){content.append(element('h3',covered?'Areas covered':'Areas to explore further'));const list=element('ul','');const areas=state.areas.filter(a=>a.covered===covered);if(areas.length)areas.forEach(a=>list.append(element('li',a.name)));else list.append(element('li',covered?'No areas covered yet.':'All scripted areas covered.'));content.append(list);}if(state.feedback.length){content.append(element('h3','Original scenario feedback'));state.feedback.forEach(text=>content.append(element('p',text)));}content.append(element('h3','Time taken'),element('p',Math.floor(state.elapsedSeconds/60)+' minutes '+state.elapsedSeconds%60+' seconds since starting this consultation.'),element('h3','What should I do next?'),element('p','Practise documenting a risk assessment for this simulated patient. Discuss your formulation and management plan with your psychiatry supervisor.'),element('p','As in the original exercise, thinking time between questions makes this longer than a conversation in practice.'));$('feedback-dialog').showModal();}
$('question-form').addEventListener('submit',e=>{e.preventDefault();ask($('question').value.trim());});$('restart').addEventListener('click',start);$('review').addEventListener('click',review);$('close-feedback').addEventListener('click',()=>$('feedback-dialog').close());$('video').addEventListener('error',()=>{if(!$('video').getAttribute('src'))return;$('video').hidden=true;$('video-placeholder').hidden=false;$('placeholder-title').textContent='Clip unavailable';$('placeholder-detail').textContent='This video could not be played. Its original transcript remains available.';$('video-error').hidden=false;});start();
